package com.primehr.performancemanagement.application;
import com.primehr.performancemanagement.api.PerformanceManagementDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.shared.api.PageResponse;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Transactional public class PerformanceCycleServiceImpl implements PerformanceCycleService{
 private final PerformanceCycleRepository cycles;private final PerformanceCycleMilestoneRepository milestones;private final PerformancePolicyVersionRepository policies;private final PrimeHrAuditService audit;
 public PerformanceCycleServiceImpl(PerformanceCycleRepository c,PerformanceCycleMilestoneRepository m,PerformancePolicyVersionRepository p,PrimeHrAuditService a){cycles=c;milestones=m;policies=p;audit=a;}
 @Override@Transactional(readOnly=true)public PageResponse<CycleResponse>list(String agency,int page,int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");return PageResponse.from(cycles.findByAgencyId(agency,PageRequest.of(page,size,Sort.by("periodStart").descending())),c->response(agency,c));}
 @Override@Transactional(readOnly=true)public CycleResponse get(String agency,String id){return response(agency,cycle(agency,id));}
 @Override public CycleResponse create(String agency,CycleInput r,String correlation){if(r.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must not be supplied when creating");String code=r.code().trim().toUpperCase(Locale.ROOT);if(cycles.existsByAgencyIdAndNormalizedCode(agency,code))throw new IllegalArgumentException("Performance cycle code already exists");requirePolicy(agency,r.policyVersionId());PerformanceCycle c=cycles.saveAndFlush(new PerformanceCycle(agency,r.code(),r.name(),r.periodStart(),r.periodEnd(),r.policyVersionId(),r.timezone()));CycleResponse after=response(agency,c);audit.record(agency,"CREATE_PERFORMANCE_CYCLE_DRAFT","SPMS_CYCLE",c.getId(),null,c.getVersion(),null,after,null,correlation);return after;}
 @Override public CycleResponse update(String agency,String id,CycleInput r,String correlation){PerformanceCycle c=cycle(agency,id);PerformancePolicyServiceImpl.requireVersion(c.getVersion(),r.recordVersion());requirePolicy(agency,r.policyVersionId());CycleResponse before=response(agency,c);c.update(r.code(),r.name(),r.periodStart(),r.periodEnd(),r.policyVersionId(),r.timezone());c=cycles.saveAndFlush(c);CycleResponse after=response(agency,c);audit.record(agency,"UPDATE_PERFORMANCE_CYCLE_DRAFT","SPMS_CYCLE",id,null,c.getVersion(),before,after,null,correlation);return after;}
 @Override public CycleResponse milestones(String agency,String id,MilestonesInput r,String correlation){PerformanceCycle c=cycle(agency,id);PerformancePolicyServiceImpl.requireVersion(c.getVersion(),r.recordVersion());if(c.getStatus()!=PerformanceCycle.Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a draft cycle calendar may be replaced");validateCalendar(c,r.milestones(),false);CycleResponse before=response(agency,c);milestones.deleteByAgencyIdAndCycleId(agency,id);milestones.saveAll(r.milestones().stream().map(v->new PerformanceCycleMilestone(agency,id,v.type(),v.key(),v.label(),v.startsAt(),v.endsAt(),v.required(),v.displayOrder(),v.instructions(),v.postCycleCloseout())).toList());milestones.flush();c.calendarChanged();c=cycles.saveAndFlush(c);CycleResponse after=response(agency,c);audit.record(agency,"REPLACE_PERFORMANCE_CYCLE_CALENDAR","SPMS_CYCLE",id,null,c.getVersion(),before,after,null,correlation);return after;}
 @Override public CycleResponse open(String agency,String id,CycleTransition r,String correlation){PerformanceCycle c=cycle(agency,id);PerformancePolicyServiceImpl.requireVersion(c.getVersion(),r.recordVersion());PerformancePolicyVersion p=requirePolicy(agency,c.getPolicyVersionId());if(p.getStatus()!=PerformancePolicyVersion.Status.PUBLISHED||p.getEffectiveFrom().isAfter(c.getPeriodStart())||p.getEffectiveTo()!=null&&p.getEffectiveTo().isBefore(c.getPeriodEnd()))throw new IllegalArgumentException("Cycle requires a published policy effective for its complete period");if(cycles.overlapping(agency,c.getPeriodStart(),c.getPeriodEnd()).stream().anyMatch(v->!v.getId().equals(id)))throw new IllegalArgumentException("Performance cycle overlaps another active cycle");List<PerformanceCycleMilestone> values=milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(agency,id);validateStoredCalendar(c,p,values);CycleResponse before=response(agency,c);c.open(audit.currentActor(),r.reason(),Instant.now());c=cycles.saveAndFlush(c);CycleResponse after=response(agency,c);audit.record(agency,"OPEN_PERFORMANCE_CYCLE","SPMS_CYCLE",id,null,c.getVersion(),before,after,r.reason(),correlation);return after;}
 @Override public CycleResponse close(String agency,String id,CycleTransition r,String correlation){return transition(agency,id,r,correlation,true);}@Override public CycleResponse cancel(String agency,String id,CycleTransition r,String correlation){return transition(agency,id,r,correlation,false);}
 private CycleResponse transition(String agency,String id,CycleTransition r,String correlation,boolean close){PerformanceCycle c=cycle(agency,id);PerformancePolicyServiceImpl.requireVersion(c.getVersion(),r.recordVersion());CycleResponse before=response(agency,c);if(close)c.close(audit.currentActor(),r.reason(),Instant.now());else c.cancel(audit.currentActor(),r.reason(),Instant.now());c=cycles.saveAndFlush(c);CycleResponse after=response(agency,c);audit.record(agency,close?"CLOSE_PERFORMANCE_CYCLE":"CANCEL_PERFORMANCE_CYCLE","SPMS_CYCLE",id,null,c.getVersion(),before,after,r.reason(),correlation);return after;}
 private void validateStoredCalendar(PerformanceCycle c,PerformancePolicyVersion p,List<PerformanceCycleMilestone> values){List<MilestoneInput> inputs=values.stream().map(v->new MilestoneInput(v.getType(),v.getMilestoneKey(),v.getLabel(),v.getStartsAt(),v.getEndsAt(),v.isRequired(),v.getDisplayOrder(),v.getInstructions(),v.isPostCycleCloseout())).toList();validateCalendar(c,inputs,true);Set<PerformanceCycleMilestone.Type> required=EnumSet.of(PerformanceCycleMilestone.Type.PLANNING_OPEN,PerformanceCycleMilestone.Type.PLANNING_DUE,PerformanceCycleMilestone.Type.APPROVAL_DUE,PerformanceCycleMilestone.Type.MONITORING_START,PerformanceCycleMilestone.Type.ACCOMPLISHMENT_DUE,PerformanceCycleMilestone.Type.RATING_DUE,PerformanceCycleMilestone.Type.FINALIZATION_DUE);if(p.isRequiresMidCycleReview())required.add(PerformanceCycleMilestone.Type.MID_CYCLE_REVIEW);if(p.isRequiresPmtCalibration())required.add(PerformanceCycleMilestone.Type.CALIBRATION_DUE);if(p.isRequiresAcknowledgment())required.add(PerformanceCycleMilestone.Type.ACKNOWLEDGMENT_DUE);if(p.isRequiresAppeal())required.add(PerformanceCycleMilestone.Type.APPEAL_DUE);Set<PerformanceCycleMilestone.Type> present=EnumSet.noneOf(PerformanceCycleMilestone.Type.class);inputs.stream().filter(MilestoneInput::required).map(MilestoneInput::type).forEach(present::add);if(!present.containsAll(required)){required.removeAll(present);throw new IllegalArgumentException("Required calendar milestones are missing: "+required);}}
 private void validateCalendar(PerformanceCycle c,List<MilestoneInput> values,boolean opening){Set<String> keys=new HashSet<>();Set<Integer> orders=new HashSet<>();Instant prior=null;ZoneId zone=ZoneId.of(c.getTimezone());Instant from=c.getPeriodStart().atStartOfDay(zone).toInstant();Instant through=c.getPeriodEnd().plusDays(1).atStartOfDay(zone).toInstant();for(MilestoneInput v:values.stream().sorted(Comparator.comparingInt(MilestoneInput::displayOrder)).toList()){String key=v.key().trim().toUpperCase(Locale.ROOT);if(!keys.add(key)||!orders.add(v.displayOrder()))throw new IllegalArgumentException("Calendar milestone key and displayOrder must be unique");if(prior!=null&&v.startsAt().isBefore(prior))throw new IllegalArgumentException("Calendar milestones must be chronological");prior=v.startsAt();if(!v.postCycleCloseout()&&(v.startsAt().isBefore(from)||!v.startsAt().isBefore(through)))throw new IllegalArgumentException("Calendar milestone must fall inside the cycle period");if(v.postCycleCloseout()&&v.startsAt().isBefore(through))throw new IllegalArgumentException("Post-cycle milestone must start after the cycle period");if(opening&&!v.required()&&v.type()!=PerformanceCycleMilestone.Type.CUSTOM){/* optional controlled milestones are allowed */}}}
 private PerformancePolicyVersion requirePolicy(String agency,String id){return policies.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Performance policy version not found"));}private PerformanceCycle cycle(String a,String id){return cycles.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance cycle not found"));}
 private CycleResponse response(String agency,PerformanceCycle c){return new CycleResponse(c.getId(),c.getCode(),c.getName(),c.getPeriodStart(),c.getPeriodEnd(),c.getPolicyVersionId(),c.getTimezone(),c.getCoverageScope(),c.getStatus().name(),c.getCalendarRevision(),c.getTransitionReason(),c.getVersion(),milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(agency,c.getId()).stream().map(v->new MilestoneResponse(v.getId(),v.getType().name(),v.getMilestoneKey(),v.getLabel(),v.getStartsAt(),v.getEndsAt(),v.isRequired(),v.getDisplayOrder(),v.getInstructions(),v.isPostCycleCloseout())).toList());}
}
